import React, { useState, useEffect } from 'react';
import { 
  Home as HomeIcon, 
  Search, 
  PlusCircle, 
  Heart, 
  User as UserIcon, 
  Bell, 
  Settings, 
  ShieldCheck, 
  DollarSign,
  Calendar,
  Phone,
  MessageCircle,
  Menu,
  X,
  CheckCircle2,
  AlertCircle,
  Trophy,
  History,
  FileText
} from 'lucide-react';
import { User, BloodRequest, Notice, DonationEvent, MoneyDonation, UserRole } from './types';
import { mockCurrentUser, initialNotices, initialEvents, initialRequests, initialDonors, initialDonations } from './store';

// Views
import HomeView from './views/Home';
import SearchView from './views/Search';
import RequestView from './views/Requests';
import DonationView from './views/Donations';
import ProfileView from './views/Profile';
import AdminDashboardView from './views/AdminDashboard';
import AuthView from './views/Auth';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(mockCurrentUser); // Start logged in for demo
  const [activeTab, setActiveTab] = useState('home');
  const [notices] = useState<Notice[]>(initialNotices);
  const [events] = useState<DonationEvent[]>(initialEvents);
  const [requests, setRequests] = useState<BloodRequest[]>(initialRequests);
  const [donors] = useState<User[]>(initialDonors);
  const [moneyDonations, setMoneyDonations] = useState<MoneyDonation[]>(initialDonations);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Simulated Tab Routing
  const renderContent = () => {
    if (!currentUser) return <AuthView onLogin={(user) => setCurrentUser(user)} />;

    switch (activeTab) {
      case 'home': return <HomeView notices={notices} events={events} onNavigate={setActiveTab} />;
      case 'search': return <SearchView donors={donors} />;
      case 'request': return <RequestView requests={requests} setRequests={setRequests} user={currentUser} />;
      case 'donations': return <DonationView donations={moneyDonations} setDonations={setMoneyDonations} user={currentUser} />;
      case 'profile': return <ProfileView user={currentUser} setUser={setCurrentUser} />;
      case 'admin': return <AdminDashboardView requests={requests} setRequests={setRequests} donations={moneyDonations} setDonations={setMoneyDonations} donors={donors} />;
      default: return <HomeView notices={notices} events={events} onNavigate={setActiveTab} />;
    }
  };

  const isAdmin = currentUser && [UserRole.ADMIN, UserRole.MAIN_ADMIN, UserRole.MODERATOR].includes(currentUser.role);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <header className="md:hidden bg-red-600 text-white p-4 flex justify-between items-center sticky top-0 z-50 shadow-md">
        <div className="flex items-center space-x-2">
          <Heart className="fill-white text-white" />
          <h1 className="text-xl font-bold tracking-tight">FBDM</h1>
        </div>
        <div className="flex items-center space-x-4">
          <Bell size={24} className="cursor-pointer" />
          <button onClick={() => setIsSidebarOpen(true)}>
            <Menu size={24} />
          </button>
        </div>
      </header>

      {/* Sidebar (Desktop & Mobile Overlay) */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 w-64 bg-white shadow-2xl transform transition-transform duration-300 ease-in-out md:translate-x-0 md:static md:block
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 h-full flex flex-col">
          <div className="flex items-center justify-between mb-8 md:justify-center">
            <div className="flex items-center space-x-2 text-red-600">
              <Heart className="fill-red-600" />
              <span className="text-2xl font-black italic">FBDM</span>
            </div>
            <button className="md:hidden text-slate-400" onClick={() => setIsSidebarOpen(false)}>
              <X size={24} />
            </button>
          </div>

          <nav className="flex-1 space-y-2">
            <NavItem icon={<HomeIcon size={20} />} label="Home" active={activeTab === 'home'} onClick={() => {setActiveTab('home'); setIsSidebarOpen(false);}} />
            <NavItem icon={<Search size={20} />} label="Donor Search" active={activeTab === 'search'} onClick={() => {setActiveTab('search'); setIsSidebarOpen(false);}} />
            <NavItem icon={<PlusCircle size={20} />} label="Request Blood" active={activeTab === 'request'} onClick={() => {setActiveTab('request'); setIsSidebarOpen(false);}} />
            <NavItem icon={<DollarSign size={20} />} label="Donate Money" active={activeTab === 'donations'} onClick={() => {setActiveTab('donations'); setIsSidebarOpen(false);}} />
            <NavItem icon={<UserIcon size={20} />} label="My Profile" active={activeTab === 'profile'} onClick={() => {setActiveTab('profile'); setIsSidebarOpen(false);}} />

            {isAdmin && (
              <div className="pt-6 mt-6 border-t border-slate-100">
                <p className="px-4 text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2">Management</p>
                <NavItem icon={<ShieldCheck size={20} />} label="Admin Panel" active={activeTab === 'admin'} onClick={() => {setActiveTab('admin'); setIsSidebarOpen(false);}} />
              </div>
            )}
          </nav>

          {currentUser && (
            <div className="pt-6 border-t border-slate-100 mt-auto">
              <div className="flex items-center space-x-3 px-4 py-2">
                <div className="w-10 h-10 rounded-full bg-red-100 flex items-center justify-center text-red-600 font-bold uppercase">
                  {currentUser.name.charAt(0)}
                </div>
                <div>
                  <p className="text-sm font-bold text-slate-800 leading-none mb-1">{currentUser.name}</p>
                  <p className="text-xs text-slate-500">{currentUser.bloodGroup} Group</p>
                </div>
              </div>
              <button 
                onClick={() => setCurrentUser(null)}
                className="w-full text-left px-4 py-3 text-sm font-medium text-red-500 hover:bg-red-50 rounded-lg transition-colors mt-2"
              >
                Sign Out
              </button>
            </div>
          )}
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto pb-20 md:pb-0 hide-scrollbar">
        <div className="max-w-4xl mx-auto p-4 md:p-8">
          {renderContent()}
        </div>
      </main>

      {/* Mobile Bottom Navigation */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 flex justify-around p-3 z-50">
        <BottomNavItem icon={<HomeIcon size={24} />} active={activeTab === 'home'} onClick={() => setActiveTab('home')} />
        <BottomNavItem icon={<Search size={24} />} active={activeTab === 'search'} onClick={() => setActiveTab('search')} />
        <BottomNavItem icon={<PlusCircle size={24} />} active={activeTab === 'request'} onClick={() => setActiveTab('request')} />
        <BottomNavItem icon={<DollarSign size={24} />} active={activeTab === 'donations'} onClick={() => setActiveTab('donations')} />
        <BottomNavItem icon={<UserIcon size={24} />} active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} />
      </nav>

      {/* Background Overlay for mobile sidebar */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 md:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}
    </div>
  );
};

const NavItem: React.FC<{ icon: React.ReactNode, label: string, active: boolean, onClick: () => void }> = ({ icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${active ? 'bg-red-50 text-red-600 font-bold shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
  >
    <span className={active ? 'text-red-600' : 'text-slate-400'}>{icon}</span>
    <span className="text-sm">{label}</span>
  </button>
);

const BottomNavItem: React.FC<{ icon: React.ReactNode, active: boolean, onClick: () => void }> = ({ icon, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center transition-colors ${active ? 'text-red-600' : 'text-slate-400'}`}
  >
    {icon}
  </button>
);

export default App;

import React, { useState } from 'react';
import { Search as SearchIcon, MapPin, Phone, MessageSquare, Filter, CheckCircle } from 'lucide-react';
import { User, BloodGroup } from '../types';

interface SearchProps {
  donors: User[];
}

const BLOOD_GROUPS: BloodGroup[] = ['A+', 'A-', 'B+', 'B-', 'O+', 'O-', 'AB+', 'AB-'];

const SearchView: React.FC<SearchProps> = ({ donors }) => {
  const [searchGroup, setSearchGroup] = useState<BloodGroup | 'ALL'>('ALL');
  const [searchLocation, setSearchLocation] = useState('');

  const filteredDonors = donors.filter(donor => {
    const groupMatch = searchGroup === 'ALL' || donor.bloodGroup === searchGroup;
    const locationMatch = donor.address.toLowerCase().includes(searchLocation.toLowerCase()) || 
                         donor.upazila.toLowerCase().includes(searchLocation.toLowerCase());
    return groupMatch && locationMatch && donor.isApproved;
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header>
        <h2 className="text-2xl font-black text-slate-800 mb-2">Find Donors</h2>
        <p className="text-sm text-slate-500">Search reliable blood donors in Mymensingh area.</p>
      </header>

      {/* Filter Section */}
      <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div>
          <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 block">Blood Group</label>
          <div className="flex flex-wrap gap-2">
            <button 
              onClick={() => setSearchGroup('ALL')}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${searchGroup === 'ALL' ? 'bg-red-600 text-white shadow-md scale-105' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}`}
            >
              All
            </button>
            {BLOOD_GROUPS.map(group => (
              <button 
                key={group}
                onClick={() => setSearchGroup(group)}
                className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${searchGroup === group ? 'bg-red-600 text-white shadow-md scale-105' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}`}
              >
                {group}
              </button>
            ))}
          </div>
        </div>

        <div className="relative">
          <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by area (e.g. Sadar, Trishal, Medical...)"
            value={searchLocation}
            onChange={(e) => setSearchLocation(e.target.value)}
            className="w-full bg-slate-50 border-none rounded-2xl py-3 pl-12 pr-4 text-sm focus:ring-2 focus:ring-red-100 transition-all outline-none"
          />
        </div>
      </div>

      {/* Results List */}
      <div className="space-y-4">
        <div className="flex items-center justify-between px-1">
          <p className="text-sm font-bold text-slate-800">{filteredDonors.length} Donors Found</p>
          <button className="text-slate-400"><Filter size={18} /></button>
        </div>

        {filteredDonors.length > 0 ? (
          filteredDonors.map(donor => (
            <div key={donor.id} className="bg-white rounded-3xl p-5 shadow-sm border border-slate-100 flex items-start gap-4 hover:shadow-md transition-shadow">
              <div className="relative">
                <div className="w-16 h-16 rounded-2xl bg-slate-100 flex items-center justify-center text-slate-400">
                  {donor.profilePic ? <img src={donor.profilePic} className="w-full h-full object-cover rounded-2xl" alt="" /> : <UserIcon size={24} />}
                </div>
                <div className="absolute -bottom-1 -right-1 w-7 h-7 bg-red-600 rounded-lg flex items-center justify-center text-white text-[10px] font-bold border-2 border-white">
                  {donor.bloodGroup}
                </div>
              </div>

              <div className="flex-1">
                <div className="flex items-center justify-between mb-1">
                  <h4 className="font-bold text-slate-800 text-base">{donor.name}</h4>
                  {donor.isAvailable && (
                    <span className="flex items-center gap-1 text-[10px] bg-green-100 text-green-600 px-2 py-0.5 rounded-full font-bold">
                      <CheckCircle size={10} /> AVAILABLE
                    </span>
                  )}
                </div>

                <p className="text-xs text-slate-500 flex items-center gap-1 mb-3">
                  <MapPin size={12} /> {donor.upazila}, {donor.district}
                </p>

                <div className="flex gap-2">
                  <button className="flex-1 bg-red-50 text-red-600 flex items-center justify-center gap-2 py-2 rounded-xl text-xs font-bold hover:bg-red-100 transition-colors">
                    <Phone size={14} /> Call
                  </button>
                  <button className="flex-1 bg-green-50 text-green-600 flex items-center justify-center gap-2 py-2 rounded-xl text-xs font-bold hover:bg-green-100 transition-colors">
                    <MessageSquare size={14} /> WhatsApp
                  </button>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="py-20 text-center space-y-4">
            <div className="bg-slate-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto text-slate-300">
              <SearchIcon size={32} />
            </div>
            <div>
              <p className="font-bold text-slate-800">No donors found</p>
              <p className="text-xs text-slate-500">Try adjusting your filters or search area.</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SearchView;

import React, { useState } from 'react';
import { User as UserIcon, Settings, Calendar, History, Trophy, Edit3, MapPin, Phone, MessageSquare, Facebook, Mail } from 'lucide-react';
import { User, BloodGroup } from '../types';

interface ProfileProps {
  user: User;
  setUser: React.Dispatch<React.SetStateAction<User | null>>;
}

const ProfileView: React.FC<ProfileProps> = ({ user, setUser }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({...user});

  const getBadge = (count: number) => {
    if (count >= 8) return { label: 'Gold Donor', icon: '🥇', color: 'text-amber-500 bg-amber-50' };
    if (count >= 4) return { label: 'Silver Donor', icon: '🥈', color: 'text-slate-400 bg-slate-50' };
    if (count >= 1) return { label: 'Bronze Donor', icon: '🥉', color: 'text-orange-500 bg-orange-50' };
    return { label: 'Supporter', icon: '🌱', color: 'text-green-500 bg-green-50' };
  };

  const badge = getBadge(user.donationsCount);

  const calculateNextDate = (last: string | null) => {
    if (!last) return 'Available Now';
    const lastDate = new Date(last);
    const nextDate = new Date(lastDate.setMonth(lastDate.getMonth() + 4));
    const today = new Date();
    if (nextDate <= today) return 'Available Now';
    return nextDate.toLocaleDateString();
  };

  const nextEligible = calculateNextDate(user.lastDonationDate);

  const handleSave = () => {
    setUser(editData);
    setIsEditing(false);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex items-center justify-between">
        <h2 className="text-2xl font-black text-slate-800">Profile Settings</h2>
        <button 
          onClick={() => setIsEditing(!isEditing)} 
          className="p-2 bg-slate-100 text-slate-600 rounded-xl hover:bg-slate-200 transition-all"
        >
          {isEditing ? 'Cancel' : <Edit3 size={20} />}
        </button>
      </header>

      {/* Profile Card */}
      <section className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 text-center relative overflow-hidden">
        <div className="relative z-10">
          <div className="w-24 h-24 rounded-[2rem] bg-red-100 text-red-600 mx-auto flex items-center justify-center text-3xl font-black mb-4 border-4 border-white shadow-lg shadow-red-50">
            {user.profilePic ? <img src={user.profilePic} className="w-full h-full object-cover rounded-[1.8rem]" alt="" /> : user.name.charAt(0)}
          </div>
          <h3 className="text-xl font-black text-slate-800">{user.name}</h3>
          <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1 mb-6">{user.role}</p>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-1">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Blood</p>
              <p className="text-lg font-black text-red-600">{user.bloodGroup}</p>
            </div>
            <div className="space-y-1">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Donated</p>
              <p className="text-lg font-black text-slate-800">{user.donationsCount}</p>
            </div>
            <div className="space-y-1">
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Badge</p>
              <p className="text-lg">{badge.icon}</p>
            </div>
          </div>
        </div>
        <div className="absolute top-0 right-0 w-32 h-32 bg-red-50 rounded-full -mr-16 -mt-16"></div>
      </section>

      {isEditing ? (
        <section className="bg-white rounded-[2.5rem] p-8 shadow-sm border border-slate-100 space-y-5 animate-in slide-in-from-top-4">
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
            <input value={editData.name} onChange={e => setEditData({...editData, name: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Blood Group</label>
              <select value={editData.bloodGroup} onChange={e => setEditData({...editData, bloodGroup: e.target.value as BloodGroup})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm">
                <option>A+</option><option>A-</option><option>B+</option><option>B-</option>
                <option>O+</option><option>O-</option><option>AB+</option><option>AB-</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Upazila</label>
              <input value={editData.upazila} onChange={e => setEditData({...editData, upazila: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm" />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Full Address</label>
            <textarea value={editData.address} onChange={e => setEditData({...editData, address: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm" rows={2}></textarea>
          </div>
