              <span className="mx-2">or</span>
              <button type="button" onClick={() => { setFlowState('PHONE_INPUT'); setError(null); }} className="font-bold text-red-600 hover:underline">Change Number</button>
            </div>
          </form>
        )}
        {error && <p className="text-xs text-red-500 text-center mt-4 bg-red-50 p-3 rounded-xl">{error}</p>}
      </div>
    </div>
  );
};

