  Bell, 
  ShieldCheck, 
  DollarSign,
  Menu,
  X,
  LoaderCircle
} from 'lucide-react';
import { collection, query, onSnapshot, doc, getDoc, orderBy } from 'firebase/firestore';
import { onAuthStateChanged } from 'firebase/auth';
import { auth, db } from './firebaseConfig';
import { User, BloodRequest, Notice, DonationEvent, MoneyDonation, UserRole } from './types';
import { initialNotices, initialEvents } from './store';

// Views
import HomeView from './views/Home';
import SearchView from './views/Search';
import RequestView from './views/Requests';
import DonationView from './views/Donations';
import ProfileView from './views/Profile';
import AdminDashboardView from './views/AdminDashboard';
import AuthView from './views/Auth';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [activeTab, setActiveTab] = useState('home');
  const [notices] = useState<Notice[]>(initialNotices);
  const [events] = useState<DonationEvent[]>(initialEvents);
  const [requests, setRequests] = useState<BloodRequest[]>([]);
  const [donors, setDonors] = useState<User[]>([]);
  const [moneyDonations, setMoneyDonations] = useState<MoneyDonation[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Handle Auth State
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        const userDocRef = doc(db, "users", user.uid);
        const userDocSnap = await getDoc(userDocRef);
        if (userDocSnap.exists()) {
          setCurrentUser({ id: user.uid, ...userDocSnap.data() } as User);
        } else {
          console.error("User document not found for logged in user.");
          await auth.signOut();
          setCurrentUser(null); 
        }
      } else {
        setCurrentUser(null);
      }
      setAuthChecked(true);
    });

    return () => unsubscribe();
  }, []);

  // Handle Firestore subscriptions
  useEffect(() => {
    if (!currentUser) {
        setRequests([]);
        setDonors([]);
        setMoneyDonations([]);
        return;
    };

    const requestsQuery = query(collection(db, "requests"), orderBy("createdAt", "desc"));
    const unsubscribeRequests = onSnapshot(requestsQuery, (snapshot) => {
        const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as BloodRequest));
        setRequests(data);
    });

    const donorsQuery = query(collection(db, "users"));
    const unsubscribeDonors = onSnapshot(donorsQuery, (snapshot) => {
        const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as User));
        setDonors(data);
    });

    const donationsQuery = query(collection(db, "donations"), orderBy("date", "desc"));
    const unsubscribeDonations = onSnapshot(donationsQuery, (snapshot) => {
        const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as MoneyDonation));
        setMoneyDonations(data);
    });

    return () => {
      unsubscribeRequests();
      unsubscribeDonors();
      unsubscribeDonations();
    };
  }, [currentUser]);

  const handleLogout = async () => {
    await auth.signOut();
    setCurrentUser(null);
    setActiveTab('home');
    setIsSidebarOpen(false);
  };

  const renderContent = () => {
    if (!authChecked) {
      return (
        <div className="flex justify-center items-center h-screen">
          <LoaderCircle size={48} className="animate-spin text-red-600" />
        </div>
      );
    }
    if (!currentUser) return <AuthView onLogin={(user) => setCurrentUser(user)} />;

    switch (activeTab) {
      case 'home': return <HomeView notices={notices} events={events} onNavigate={setActiveTab} />;
      case 'search': return <SearchView donors={donors} />;
      case 'request': return <RequestView requests={requests} user={currentUser} />;
      case 'donations': return <DonationView donations={moneyDonations} user={currentUser} />;
      case 'profile': return <ProfileView user={currentUser} setUser={setCurrentUser} />;
      case 'admin': return <AdminDashboardView requests={requests} donations={moneyDonations} donors={donors} currentUser={currentUser} />;
      default: return <HomeView notices={notices} events={events} onNavigate={setActiveTab} />;
    }
  };

  const isAdmin = currentUser && [UserRole.ADMIN, UserRole.MAIN_ADMIN, UserRole.MODERATOR].includes(currentUser.role);

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col md:flex-row">
      {/* Mobile Header */}
      <header className="md:hidden bg-red-600 text-white p-4 flex justify-between items-center sticky top-0 z-50 shadow-md">
        <div className="flex items-center space-x-2">
          <Heart className="fill-white text-white" />
          <h1 className="text-xl font-bold tracking-tight">FBDM</h1>
        </div>
        <div className="flex items-center space-x-4">
          <Bell size={24} className="cursor-pointer" />
          {currentUser && (
            <button onClick={() => setIsSidebarOpen(true)}>
              <Menu size={24} />
            </button>
          )}
        </div>
      </header>

      {/* Sidebar (Desktop & Mobile Overlay) */}
      {currentUser && (
        <aside className={`
          fixed inset-y-0 left-0 z-50 w-64 bg-white shadow-2xl transform transition-transform duration-300 ease-in-out md:translate-x-0 md:static md:block
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        `}>
          <div className="p-6 h-full flex flex-col">
            <div className="flex items-center justify-between mb-8 md:justify-center">
              <div className="flex items-center space-x-2 text-red-600">
                <Heart className="fill-red-600" />
                <span className="text-2xl font-black italic">FBDM</span>
              </div>
              <button className="md:hidden text-slate-400" onClick={() => setIsSidebarOpen(false)}>
                <X size={24} />
              </button>
            </div>

            <nav className="flex-1 space-y-2">
              <NavItem icon={<HomeIcon size={20} />} label="Home" active={activeTab === 'home'} onClick={() => {setActiveTab('home'); setIsSidebarOpen(false);}} />
              <NavItem icon={<Search size={20} />} label="Donor Search" active={activeTab === 'search'} onClick={() => {setActiveTab('search'); setIsSidebarOpen(false);}} />
              <NavItem icon={<PlusCircle size={20} />} label="Request Blood" active={activeTab === 'request'} onClick={() => {setActiveTab('request'); setIsSidebarOpen(false);}} />
              <NavItem icon={<DollarSign size={20} />} label="Donate Money" active={activeTab === 'donations'} onClick={() => {setActiveTab('donations'); setIsSidebarOpen(false);}} />
              <NavItem icon={<UserIcon size={20} />} label="My Profile" active={activeTab === 'profile'} onClick={() => {setActiveTab('profile'); setIsSidebarOpen(false);}} />

              {isAdmin && (
                <div className="pt-6 mt-6 border-t border-slate-100">
                  <p className="px-4 text-xs font-semibold text-slate-400 uppercase tracking-wider mb-2">Management</p>
                  <NavItem icon={<ShieldCheck size={20} />} label="Admin Panel" active={activeTab === 'admin'} onClick={() => {setActiveTab('admin'); setIsSidebarOpen(false);}} />
                </div>
              )}
            </nav>

            <div className="pt-6 border-t border-slate-100 mt-auto">
              <div className="flex items-center space-x-3 px-4 py-2">
                <div className="w-10 h-10 rounded-full bg-red-100 flex items-center justify-center text-red-600 font-bold uppercase">
                  {currentUser.name.charAt(0)}
                </div>
                <div>
                  <p className="text-sm font-bold text-slate-800 leading-none mb-1">{currentUser.name}</p>
                  <p className="text-xs text-slate-500">{currentUser.bloodGroup} Group</p>
                </div>
              </div>
              <button 
                onClick={handleLogout}
                className="w-full text-left px-4 py-3 text-sm font-medium text-red-500 hover:bg-red-50 rounded-lg transition-colors mt-2"
              >
                Sign Out
              </button>
            </div>
          </div>
        </aside>
      )}

      {/* Main Content Area */}
      <main className="flex-1 overflow-y-auto pb-20 md:pb-0 hide-scrollbar">
        <div className="max-w-4xl mx-auto p-4 md:p-8">
          {renderContent()}
        </div>
      </main>

      {/* Mobile Bottom Navigation */}
      {currentUser && (
        <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 flex justify-around p-3 z-50">
          <BottomNavItem icon={<HomeIcon size={24} />} active={activeTab === 'home'} onClick={() => setActiveTab('home')} />
          <BottomNavItem icon={<Search size={24} />} active={activeTab === 'search'} onClick={() => setActiveTab('search')} />
          <BottomNavItem icon={<PlusCircle size={24} />} active={activeTab === 'request'} onClick={() => setActiveTab('request')} />
          <BottomNavItem icon={<DollarSign size={24} />} active={activeTab === 'donations'} onClick={() => setActiveTab('donations')} />
          <BottomNavItem icon={<UserIcon size={24} />} active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} />
        </nav>
      )}

      {/* Background Overlay for mobile sidebar */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 md:hidden" 
          onClick={() => setIsSidebarOpen(false)}
        />
      )}
    </div>
  );
};

const NavItem: React.FC<{ icon: React.ReactNode, label: string, active: boolean, onClick: () => void }> = ({ icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all ${active ? 'bg-red-50 text-red-600 font-bold shadow-sm' : 'text-slate-600 hover:bg-slate-50'}`}
  >
    <span className={active ? 'text-red-600' : 'text-slate-400'}>{icon}</span>
    <span className="text-sm">{label}</span>
  </button>
);

const BottomNavItem: React.FC<{ icon: React.ReactNode, active: boolean, onClick: () => void }> = ({ icon, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`flex flex-col items-center transition-colors ${active ? 'text-red-600' : 'text-slate-400'}`}
  >
    {icon}
  </button>
);

export default App;

import React, { useState } from 'react';
import { Plus, Clock, MapPin, Phone, Hospital, Users, CheckCircle, AlertTriangle, Send } from 'lucide-react';
import { collection, addDoc, serverTimestamp } from 'firebase/firestore';
import { db } from '../firebaseConfig';
import { BloodRequest, User, BloodGroup } from '../types';

interface RequestProps {
  requests: BloodRequest[];
  user: User;
}

const BLOOD_GROUPS: BloodGroup[] = ['A+', 'A-', 'B+', 'B-', 'O+', 'O-', 'AB+', 'AB-'];

const RequestView: React.FC<RequestProps> = ({ requests, user }) => {
  const [showModal, setShowModal] = useState(false);
  const [filter, setFilter] = useState<'ALL' | 'MINE'>('ALL');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    patientName: '',
    bloodGroup: 'A+' as BloodGroup,
    units: 1,
    hospitalName: '',
    location: '',
    requiredAt: '',
    contactNumber: '',
    isEmergency: false
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    try {
      await addDoc(collection(db, "requests"), {
        ...formData,
        units: Number(formData.units),
        requestedBy: user.id,
        status: 'PENDING',
        createdAt: serverTimestamp()
      });
      setShowModal(false);
      // Reset form
      setFormData({
        patientName: '',
        bloodGroup: 'A+' as BloodGroup,
        units: 1,
        hospitalName: '',
        location: '',
        requiredAt: '',
        contactNumber: '',
        isEmergency: false
      });
    } catch (error) {
      console.error("Error creating request:", error);
      // Ideally, show an error message to the user here
    } finally {
      setIsSubmitting(false);
    }
  };

  const filteredRequests = filter === 'MINE' 
    ? requests.filter(r => r.requestedBy === user.id)
    : requests.filter(r => r.status === 'APPROVED' || r.requestedBy === user.id);

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
      <header className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-800 mb-1">Blood Requests</h2>
          <p className="text-sm text-slate-500">Post or find urgent blood requirements.</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-red-600 text-white p-3 rounded-2xl shadow-lg shadow-red-200 hover:scale-105 active:scale-95 transition-all"
        >
          <Plus size={24} />
        </button>
      </header>

      {/* Tabs */}
      <div className="flex p-1 bg-slate-100 rounded-2xl w-fit">
        <button 
          onClick={() => setFilter('ALL')}
          className={`px-6 py-2 rounded-xl text-xs font-bold transition-all ${filter === 'ALL' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
        >
          Active Feed
        </button>
        <button 
          onClick={() => setFilter('MINE')}
          className={`px-6 py-2 rounded-xl text-xs font-bold transition-all ${filter === 'MINE' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
        >
          My Posts
        </button>
      </div>

      {/* Feed */}
      <div className="space-y-4">
        {filteredRequests.map(req => (
          <div key={req.id} className={`bg-white rounded-3xl p-6 shadow-sm border ${req.isEmergency ? 'border-red-100 bg-red-50/20' : 'border-slate-100'}`}>
            <div className="flex justify-between items-start mb-4">
              <div className="flex items-center gap-3">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg ${req.isEmergency ? 'bg-red-600 text-white animate-pulse' : 'bg-slate-100 text-slate-700'}`}>
                  {req.bloodGroup}
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 leading-tight">{req.patientName}</h4>
                  <div className="flex items-center gap-2 mt-0.5">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{req.units} UNIT{req.units > 1 && 'S'}</span>
                    {req.isEmergency && (
                      <span className="flex items-center gap-1 text-[8px] bg-red-100 text-red-600 px-1.5 py-0.5 rounded-full font-black">
                        <AlertTriangle size={8} /> EMERGENCY
                      </span>
                    )}
                  </div>
                </div>
              </div>
              <div className="text-right">
                <div className={`text-[10px] font-bold px-2 py-1 rounded-full ${req.status === 'APPROVED' ? 'bg-green-100 text-green-600' : req.status === 'PENDING' ? 'bg-amber-100 text-amber-600' : req.status === 'FULFILLED' ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-400'}`}>
                  {req.status}
                </div>
                <p className="text-[10px] text-slate-400 mt-1 font-medium">{req.createdAt?.toDate().toLocaleDateString()}</p>
              </div>
            </div>

            <div className="space-y-3 mb-5">
              <div className="flex items-start gap-2 text-xs text-slate-600">
                <Hospital size={14} className="text-slate-400 mt-0.5" />
                <span>{req.hospitalName}, {req.location}</span>
              </div>
              <div className="flex items-start gap-2 text-xs text-slate-600">
                <Clock size={14} className="text-slate-400 mt-0.5" />
                <span>Required By: <span className="font-bold text-slate-800">{req.requiredAt}</span></span>
              </div>
            </div>

            <div className="flex gap-2">
              <a href={`tel:${req.contactNumber}`} className="flex-1 bg-red-600 text-white flex items-center justify-center gap-2 py-3 rounded-2xl text-xs font-bold hover:bg-red-700 transition-all shadow-md shadow-red-100">
                <Phone size={14} /> Call Attendant
              </a>
              <button className="bg-slate-100 text-slate-600 p-3 rounded-2xl hover:bg-slate-200 transition-colors">
                <Send size={18} />
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* New Request Modal */}
      {showModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-lg rounded-[2rem] p-8 shadow-2xl relative animate-in zoom-in-95 duration-300 overflow-y-auto max-h-[90vh] hide-scrollbar">
            <button onClick={() => setShowModal(false)} className="absolute right-6 top-6 text-slate-400 hover:text-slate-600">
              <Plus size={24} className="rotate-45" />
            </button>
            <h3 className="text-2xl font-black text-slate-800 mb-2">Request Blood</h3>
            <p className="text-sm text-slate-500 mb-6">Fill in patient details for approval.</p>

            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Patient Name</label>
                <input required type="text" value={formData.patientName} onChange={e => setFormData({...formData, patientName: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="Patient's full name" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Blood Group</label>
                  <select value={formData.bloodGroup} onChange={e => setFormData({...formData, bloodGroup: e.target.value as BloodGroup})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-red-100">
                    {BLOOD_GROUPS.map(g => <option key={g} value={g}>{g}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Units Needed</label>
                  <input required type="number" min="1" value={formData.units} onChange={e => setFormData({...formData, units: parseInt(e.target.value)})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-red-100" />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Hospital Name</label>
                <input required type="text" value={formData.hospitalName} onChange={e => setFormData({...formData, hospitalName: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="e.g. MMCH, Ward 10" />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Location Details</label>
                <input required type="text" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="e.g. Town Hall Area" />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Required Date & Time</label>
                <input required type="text" value={formData.requiredAt} onChange={e => setFormData({...formData, requiredAt: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="e.g. 25 June, 10:00 PM" />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Contact Number</label>
                <input required type="tel" value={formData.contactNumber} onChange={e => setFormData({...formData, contactNumber: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="Mobile number" />
              </div>

              <div className="flex items-center gap-3 p-4 bg-red-50 rounded-2xl">
                <input type="checkbox" id="isEmergency" checked={formData.isEmergency} onChange={e => setFormData({...formData, isEmergency: e.target.checked})} className="w-5 h-5 accent-red-600 rounded" />
                <label htmlFor="isEmergency" className="text-sm font-bold text-red-600">Mark as Emergency</label>
              </div>

              <button type="submit" disabled={isSubmitting} className="w-full bg-red-600 text-white py-4 rounded-2xl font-bold shadow-lg shadow-red-100 hover:bg-red-700 transition-all mt-4 disabled:bg-red-400">
                {isSubmitting ? 'Submitting...' : 'Post Request'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default RequestView;

import React, { useState } from 'react';
import { 
  Users, 
  Droplet, 
  DollarSign, 
  CheckCircle, 
  Search, 
  MoreHorizontal, 
  ShieldAlert
} from 'lucide-react';
import { doc, updateDoc } from 'firebase/firestore';
import { db } from '../firebaseConfig';
import { BloodRequest, MoneyDonation, User, UserRole } from '../types';

interface AdminProps {
  requests: BloodRequest[];
  donations: MoneyDonation[];
  donors: User[];
  currentUser: User;
}

type AdminSubTab = 'REQUESTS' | 'DONATIONS' | 'USERS';

const AdminDashboardView: React.FC<AdminProps> = ({ requests, donations, donors, currentUser }) => {
  const [activeSubTab, setActiveSubTab] = useState<AdminSubTab>('REQUESTS');

  // Role-based access control checks
  const canManageDonations = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MAIN_ADMIN;
  const canManageUsers = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.MAIN_ADMIN;

  const pendingRequests = requests.filter(r => r.status === 'PENDING');
  const pendingDonations = donations.filter(d => d.status === 'PENDING');

  const handleApproveRequest = async (id: string) => {
    const requestDocRef = doc(db, "requests", id);
    await updateDoc(requestDocRef, { status: 'APPROVED' });
  };

  const handleRejectRequest = async (id: string) => {
    const requestDocRef = doc(db, "requests", id);
    await updateDoc(requestDocRef, { status: 'REJECTED' });
  };

  const handleApproveDonation = async (id: string) => {
    if (!canManageDonations) return;
    const donationDocRef = doc(db, "donations", id);
    await updateDoc(donationDocRef, { status: 'VERIFIED' });
  };

  const handleRejectDonation = async (id: string) => {
    if (!canManageDonations) return;
    const donationDocRef = doc(db, "donations", id);
    await updateDoc(donationDocRef, { status: 'REJECTED' });
  };

  const handleTabClick = (tab: AdminSubTab) => {
    if (tab === 'DONATIONS' && !canManageDonations) return;
    if (tab === 'USERS' && !canManageUsers) return;
    setActiveSubTab(tab);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      <header>
        <h2 className="text-3xl font-black text-slate-800">Admin Console</h2>
        <p className="text-sm text-slate-500">Centralized control for FBDM community.</p>
      </header>

      {/* Stats Overview */}
      <section className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatItem label="Total Users" value={donors.length} subValue="Community members" icon={<Users className="text-blue-600" />} />
        <StatItem label="Pending Requests" value={pendingRequests.length} subValue="High Priority" icon={<Droplet className="text-red-600" />} />
        <StatItem label="Financial Support" value={`৳${donations.reduce((a,b) => a + (b.status === 'VERIFIED' ? b.amount : 0), 0)}`} subValue="Verified Total" icon={<DollarSign className="text-green-600" />} />
        <StatItem label="Reports" value="0" subValue="Unresolved" icon={<ShieldAlert className="text-amber-600" />} />
      </section>

      {/* Sub Navigation */}
      <div className="flex space-x-4 border-b border-slate-200">
        <button onClick={() => handleTabClick('REQUESTS')} className={`pb-3 px-2 text-sm font-bold transition-all relative ${activeSubTab === 'REQUESTS' ? 'text-red-600' : 'text-slate-400'}`}>
