import React, { useState, useEffect } from 'react';
import { Heart, Phone, KeyRound, ArrowRight, LoaderCircle } from 'lucide-react';
import { RecaptchaVerifier, signInWithPhoneNumber, ConfirmationResult } from 'firebase/auth';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { auth, db } from '../firebaseConfig';
import { User, UserRole } from '../types';

interface AuthProps {
  onLogin: (user: User) => void;
}

const AuthView: React.FC<AuthProps> = ({ onLogin }) => {
  const [flowState, setFlowState] = useState<'PHONE_INPUT' | 'OTP_INPUT'>('PHONE_INPUT');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [otp, setOtp] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [confirmationResult, setConfirmationResult] = useState<ConfirmationResult | null>(null);

  // Set up reCAPTCHA verifier
  useEffect(() => {
    if (!window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
        'size': 'invisible',
        'callback': (response: any) => {
          // reCAPTCHA solved, allow signInWithPhoneNumber.
          console.log("reCAPTCHA solved");
        },
        'expired-callback': () => {
          // Response expired. Ask user to solve reCAPTCHA again.
          setError("reCAPTCHA expired. Please try again.");
        }
      });
    }
  }, []);

  const formatPhoneNumber = (number: string): string => {
    if (number.startsWith('+88')) return number;
    if (number.startsWith('01')) return `+88${number.substring(1)}`;
    return number; // Fallback
  };

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!phoneNumber || phoneNumber.length < 10) {
      setError("Please enter a valid phone number.");
      return;
    }

    setIsLoading(true);
    const formattedNumber = formatPhoneNumber(phoneNumber);
    const appVerifier = window.recaptchaVerifier!;

    try {
      const result = await signInWithPhoneNumber(auth, formattedNumber, appVerifier);
      setConfirmationResult(result);
      setFlowState('OTP_INPUT');
    } catch (err: any)
     {
      console.error("Error sending OTP:", err);
      setError("Failed to send OTP. This is likely a Firebase configuration issue. Please ensure the Phone sign-in provider is enabled in your Firebase console.");
      // Reset reCAPTCHA if it fails
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.render().then(widgetId => {
          // @ts-ignore
          if (window.grecaptcha) {
            // @ts-ignore
            grecaptcha.reset(widgetId);
          }
        });
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!otp || otp.length !== 6) {
      setError("Please enter the 6-digit code.");
      return;
    }
    if (!confirmationResult) {
      setError("Verification process failed. Please start over.");
      return;
    }

    setIsLoading(true);
    try {
      const result = await confirmationResult.confirm(otp);
      const user = result.user;

      const userDocRef = doc(db, "users", user.uid);
      const userDocSnap = await getDoc(userDocRef);

      let userProfile: User;
      if (userDocSnap.exists()) {
        userProfile = { id: user.uid, ...userDocSnap.data() } as User;
      } else {
        userProfile = {
          id: user.uid,
          name: 'New Donor',
          role: UserRole.USER,
          bloodGroup: 'A+',
          division: 'Mymensingh',
          district: 'Mymensingh',
          upazila: 'Sadar',
          address: 'Please update your address',
          mobile: user.phoneNumber!,
          whatsapp: user.phoneNumber!,
          lastDonationDate: null,
          isAvailable: true,
          isApproved: false, // New users need admin approval
          donationsCount: 0,
        };
        await setDoc(userDocRef, userProfile);
      }
      onLogin(userProfile);

    } catch (err: any) {
      console.error("Error verifying OTP:", err);
      setError("Invalid OTP code. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center p-4">
      <div id="recaptcha-container"></div>
      <div className="w-full max-w-md bg-white rounded-[3rem] p-10 shadow-2xl shadow-slate-200 animate-in zoom-in-95 duration-500">
        <div className="text-center mb-10">
          <div className="w-16 h-16 bg-red-600 rounded-3xl mx-auto flex items-center justify-center text-white mb-6 rotate-3">
            <Heart className="fill-white" size={32} />
          </div>
          <h1 className="text-3xl font-black text-slate-800">Welcome to FBDM</h1>
          <p className="text-sm text-slate-400 font-medium">
            {flowState === 'PHONE_INPUT' 
              ? 'Enter your mobile to login or register.'
              : `We've sent a code to ${phoneNumber}`}
          </p>
        </div>

        {flowState === 'PHONE_INPUT' ? (
          <form onSubmit={handleSendOtp} className="space-y-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Mobile Number</label>
              <div className="relative">
                <Phone className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input 
                  required 
                  type="tel"
                  value={phoneNumber}
                  onChange={e => setPhoneNumber(e.target.value)}
                  className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100 tracking-wider" 
                  placeholder="01XXXXXXXXX" 
                />
              </div>
            </div>
            <button type="submit" disabled={isLoading} className="w-full bg-red-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-red-100 hover:bg-red-700 transition-all active:scale-95 flex items-center justify-center gap-2 disabled:bg-red-400">
              {isLoading ? <LoaderCircle className="animate-spin" /> : <>Send OTP <ArrowRight size={20} /></>}
            </button>
          </form>
        ) : (
          <form onSubmit={handleVerifyOtp} className="space-y-6">
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Verification Code</label>
              <div className="relative">
                <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input 
                  required 
                  type="text" 
                  inputMode="numeric"
                  maxLength={6}
                  value={otp}
                  onChange={e => setOtp(e.target.value)}
                  className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100 tracking-[0.5em] text-center" 
                  placeholder="••••••" 
                />
              </div>
            </div>

            <button type="submit" disabled={isLoading} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 hover:bg-slate-800 transition-all active:scale-95 disabled:bg-slate-400 flex items-center justify-center gap-2">
              {isLoading ? <LoaderCircle className="animate-spin" /> : 'Verify & Continue'}
            </button>

            <div className="text-center text-xs text-slate-400 pt-4">
              Didn't receive a code? 
              <button type="button" className="font-bold text-red-600 hover:underline ml-1">Resend</button>
              <span className="mx-2">or</span>
              <button type="button" onClick={() => { setFlowState('PHONE_INPUT'); setError(null); }} className="font-bold text-red-600 hover:underline">Change Number</button>
            </div>
          </form>
        )}
        {error && <p className="text-xs text-red-500 text-center mt-4 bg-red-50 p-3 rounded-xl">{error}</p>}
      </div>
    </div>
  );
};

