    } finally {
      setIsLoading(false);
    }
  };

  const handleEmailLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!email || !password) {
      setError("Please enter both email and password.");
      return;
    }
    setIsLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email, password);
      // onAuthStateChanged in App.tsx will handle the login and profile fetching.
    } catch (error: any) {
      console.error("Email login error:", error);
      setError("Failed to login. Please check your email and password.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleEmailSignUp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!name || !mobile || !email || !password) {
      setError("Please fill out all fields.");
      return;
    }
    if (password.length < 6) {
      setError("Password must be at least 6 characters long.");
      return;
    }
    setIsLoading(true);
    try {
      const result = await createUserWithEmailAndPassword(auth, email, password);
      const user = result.user;
      const userProfile: User = {
        id: user.uid, name, role: UserRole.USER, bloodGroup: 'A+',
        division: 'Mymensingh', district: 'Mymensingh', upazila: 'Sadar',
        address: 'Please update your address', mobile, whatsapp: mobile, email: user.email!,
        lastDonationDate: null, isAvailable: true, isApproved: false, donationsCount: 0,
      };
      await setDoc(doc(db, "users", user.uid), userProfile);
      onLogin(userProfile);
    } catch (error: any) {
      console.error("Email signup error:", error);
      if (error.code === 'auth/email-already-in-use') {
        setError("This email is already in use. Please log in.");
      } else {
        setError("Failed to create account. Please try again.");
      }
    } finally {
      setIsLoading(false);
    }
  };

  // Legacy state for phone flow UI
  const [flowState, setFlowState] = useState<'PHONE_INPUT' | 'OTP_INPUT'>('PHONE_INPUT');

  const renderPhoneAuth = () => (
    <>
      {flowState === 'PHONE_INPUT' ? (
        <form onSubmit={handleSendOtp} className="space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Mobile Number</label>
            <div className="relative">
              <Phone className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="tel" value={phoneNumber} onChange={e => setPhoneNumber(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100 tracking-wider" placeholder="01XXXXXXXXX" />
            </div>
          </div>
          <button type="submit" disabled={isLoading} className="w-full bg-red-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-red-100 hover:bg-red-700 transition-all active:scale-95 flex items-center justify-center gap-2 disabled:bg-red-400">
            {isLoading ? <LoaderCircle className="animate-spin" /> : <>Send OTP <ArrowRight size={20} /></>}
          </button>
        </form>
      ) : (
        <form onSubmit={handleVerifyOtp} className="space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Verification Code</label>
            <div className="relative">
              <KeyRound className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="text" inputMode="numeric" maxLength={6} value={otp} onChange={e => setOtp(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100 tracking-[0.5em] text-center" placeholder="••••••" />
            </div>
          </div>
          <button type="submit" disabled={isLoading} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 hover:bg-slate-800 transition-all active:scale-95 disabled:bg-slate-400 flex items-center justify-center gap-2">
            {isLoading ? <LoaderCircle className="animate-spin" /> : 'Verify & Continue'}
          </button>
          <div className="text-center text-xs text-slate-400 pt-4">
            Didn't receive a code? <button type="button" className="font-bold text-red-600 hover:underline ml-1">Resend</button>
            <span className="mx-2">or</span>
            <button type="button" onClick={() => { setFlowState('PHONE_INPUT'); setError(null); }} className="font-bold text-red-600 hover:underline">Change Number</button>
          </div>
        </form>
      )}
    </>
  );

  const renderEmailAuth = () => (
    <>
      {emailFlow === 'LOGIN' ? (
        <form onSubmit={handleEmailLogin} className="space-y-5">
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Email</label>
            <div className="relative">
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="your@email.com" />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Password</label>
            <div className="relative">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="••••••••" />
            </div>
          </div>
          <button type="submit" disabled={isLoading} className="w-full bg-red-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-red-100 hover:bg-red-700 transition-all active:scale-95 flex items-center justify-center gap-2 disabled:bg-red-400">
            {isLoading ? <LoaderCircle className="animate-spin" /> : 'Login'}
          </button>
          <p className="text-center text-xs text-slate-400 pt-2">
            New here? <button type="button" onClick={() => setEmailFlow('SIGNUP')} className="font-bold text-red-600 hover:underline">Create an account</button>
          </p>
        </form>
      ) : ( // SIGNUP flow
        <form onSubmit={handleEmailSignUp} className="space-y-4">
           <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Full Name</label>
            <div className="relative">
              <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="Enter your name" />
            </div>
          </div>
           <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Mobile Number</label>
            <div className="relative">
              <Phone className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="tel" value={mobile} onChange={e => setMobile(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="01XXXXXXXXX" />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Email</label>
            <div className="relative">
              <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="your@email.com" />
            </div>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Password</label>
            <div className="relative">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
              <input required type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl p-4 pl-12 text-sm outline-none focus:ring-2 focus:ring-red-100" placeholder="Min. 6 characters" />
            </div>
          </div>
          <button type="submit" disabled={isLoading} className="w-full bg-red-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-red-100 hover:bg-red-700 transition-all active:scale-95 flex items-center justify-center gap-2 disabled:bg-red-400 pt-4">
            {isLoading ? <LoaderCircle className="animate-spin" /> : 'Create Account'}
          </button>
           <p className="text-center text-xs text-slate-400 pt-2">
            Already have an account? <button type="button" onClick={() => setEmailFlow('LOGIN')} className="font-bold text-red-600 hover:underline">Login here</button>
          </p>
        </form>
      )}
    </>
  );

  const getSubtitle = () => {
    if (authMethod === 'PHONE') {
      return flowState === 'PHONE_INPUT' ? 'Enter your mobile to login or register.' : `We've sent a code to ${phoneNumber}`;
    }
    if (emailFlow === 'LOGIN') return 'Login with your email and password.';
    return 'Create your FBDM account.';
  };

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center p-4">
      <div id="recaptcha-container"></div>
      <div className="w-full max-w-md bg-white rounded-[3rem] p-8 md:p-10 shadow-2xl shadow-slate-200 animate-in zoom-in-95 duration-500">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-red-600 rounded-3xl mx-auto flex items-center justify-center text-white mb-6 rotate-3">
            <Heart className="fill-white" size={32} />
          </div>
          <h1 className="text-3xl font-black text-slate-800">Welcome to FBDM</h1>
          <p className="text-sm text-slate-400 font-medium">{getSubtitle()}</p>
        </div>

        {authMethod === 'PHONE' ? renderPhoneAuth() : renderEmailAuth()}

        <div className="text-center text-xs text-slate-400 mt-6">
          <button 
            type="button" 
            onClick={() => {
              setAuthMethod(authMethod === 'PHONE' ? 'EMAIL' : 'PHONE');
              setError(null);
            }} 
            className="font-bold text-red-600 hover:underline"
          >
            {authMethod === 'PHONE' ? 'Or, continue with Email' : 'Or, continue with Phone OTP'}
          </button>
        </div>

        {error && <p className="text-xs text-red-500 text-center mt-4 bg-red-50 p-3 rounded-xl">{error}</p>}
      </div>
    </div>
  );
};

export default AuthView;
